solution.solution.py:
def slugify(title: str) -> str:
    cleaned = "".join(c if c.isalpha() or c.isdigit() else " " for c in title.lower())
    return "-".join(cleaned.split())


def parse_duration(text: str) -> int:
    total = 0
    number = ""
    last = -1                      # place in "hms" of the previous unit
    for c in text.lower():
        if c.isdigit():
            number += c
            continue
        place = "hms".find(c)
        if place == -1 or not number or place <= last:
            raise ValueError(f"invalid duration: {text}")
        total += int(number) * [3600, 60, 1][place]
        number = ""
        last = place
    if number or last == -1:       # digits with no unit, or no parts at all
        raise ValueError(f"invalid duration: {text}")
    return total

