@test("slugs")
def _():
    check_eq(slugify("Hello, World!"), "hello-world")
    check_eq(slugify("  Python 3.13 -- What's New?  "), "python-3-13-what-s-new")
    check_eq(slugify("***"), "")

@test("durations")
def _():
    check_eq(parse_duration("45s"), 45)
    check_eq(parse_duration("1h30m"), 5400)
    check_eq(parse_duration("2H"), 7200)
    check_eq(parse_duration("1h5s"), 3605)
    check_eq(parse_duration("90m"), 5400)

@test("bad durations")
def _():
    for bad in ["", "5", "5x", "1m1h", "1h1h", "h", "1h 30m", "1.5h"]:
        check_raises(ValueError, parse_duration, bad)

@test("type hints")
def _():
    check_eq(slugify.__annotations__, {"title": str, "return": str})
    check_eq(parse_duration.__annotations__, {"text": str, "return": int})

